/**
 * Interoperability with FlatGeobuf files written by other writers than GDAL:
 * gogama/flatgeobuf (Go), generated by test/fixtures/writers/gogama, and the
 * flatgeobuf npm package (JavaScript), generated by
 * test/fixtures/writers/flatgeobuf-js. Their features are those of
 * GDAL-written fixtures, whose tiles they must reproduce.
 */
import { describe, it, expect, afterAll } from 'vitest';
import { readFileSync } from 'node:fs';
import { tile } from '../../src/tile.js';
import { LocalConnector } from '../../src/connectors/local.js';
import { FgbSource, createIoContext } from '../../src/fgb/reader.js';
import { parseHeader } from '../../src/fgb/header.js';
import { decodeFeatures } from '../../src/fgb/feature.js';
import { MemoryCache } from '../../src/cache.js';
import { IndexMismatchError } from '../../src/errors.js';
import type { Source } from '../../src/source.js';
import { ColumnType, GeomType, type BBox } from '../../src/types.js';
import { fixture, decodeLayer, features, tileAt } from '../helpers/tiles.js';

const connector = new LocalConnector();
afterAll(() => connector.close());

/** Point coordinates per label (`p0`…`p199`) in a tile. */
async function pointsByLabel(path: string, z: number, x: number, y: number, useIndex = true) {
  const out = new Map<string, string>();
  for (const f of features(decodeLayer(await tile(connector, z, x, y, { name: 'l', path, useIndex }), 'l'))) {
    const [p] = f.loadGeometry()[0];
    out.set(String(f.properties.label), `${p.x},${p.y}`);
  }
  return out;
}

const TILES: Array<[number, number, number]> = [
  [0, 0, 0],
  [4, tileAt(-96, 32, 4).x, tileAt(-96, 32, 4).y],
  [8, tileAt(-96, 32, 8).x, tileAt(-96, 32, 8).y],
  [11, tileAt(-95.6, 31.4, 11).x, tileAt(-95.6, 31.4, 11).y],
];

describe('gogama/flatgeobuf', () => {
  it.each(TILES)('renders the same points as GDAL\'s file at %i/%i/%i (node size 4)', async (z, x, y) => {
    const gdal = await pointsByLabel(fixture('points.fgb'), z, x, y);
    expect(await pointsByLabel(fixture('gogama-points.fgb'), z, x, y)).toEqual(gdal);
    expect(await pointsByLabel(fixture('gogama-points-noindex.fgb'), z, x, y)).toEqual(gdal);
  });

  it('finds exactly the intersecting features with node size 4', async () => {
    const path = fixture('gogama-points.fgb');
    const bytes = new Uint8Array(readFileSync(path));
    const header = parseHeader(bytes);
    expect(header.indexNodeSize).toBe(4);
    const all = decodeFeatures(bytes.subarray(header.featuresOffset), header);
    const fgb = await FgbSource.open(connector, path, createIoContext({ cache: new MemoryCache() }, new MemoryCache()));
    let seed = 3;
    const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
    for (let q = 0; q < 50; q++) {
      const w = rand() * 6, h = rand() * 4;
      const box: BBox = { minX: -101 + rand() * 10, minY: 29 + rand() * 5, maxX: 0, maxY: 0 };
      box.maxX = box.minX + w;
      box.maxY = box.minY + h;
      const expected = all
        .filter(f => f.xy[0] >= box.minX && f.xy[0] <= box.maxX && f.xy[1] >= box.minY && f.xy[1] <= box.maxY)
        .map(f => f.id).sort();
      const got = (await fgb.readFeatures(box)).map(f => f.id).sort();
      expect(got).toEqual(expected);
    }
  });

  it('reads multipolygons with holes stored as parts', async () => {
    const { x, y } = tileAt(-120, 30, 4);
    const layer = decodeLayer(await tile(connector, 4, x, y, { name: 'l', path: fixture('gogama-polygons.fgb') }), 'l');
    const world = decodeLayer(await tile(connector, 0, 0, 0, { name: 'l', path: fixture('gogama-polygons.fgb') }), 'l');
    expect(world?.length).toBe(30);
    const first = features(layer).find(f => f.properties.label === 'p0')!;
    // Exterior with hole, plus the second polygon of the multipolygon
    expect(first.loadGeometry()).toHaveLength(3);
    expect(first.toGeoJSON(x, y, 4).geometry.type).toBe('MultiPolygon');
  });

  describe('files written with FileWriter.IndexData (v1.0.0)', () => {
    it('are rejected with an explanation', async () => {
      for (const name of ['gogama-indexdata-points.fgb', 'gogama-indexdata-polygons.fgb']) {
        const err = await tile(connector, 0, 0, 0, { name: 'l', path: fixture(name) }, { cache: false }).catch(e => e);
        expect(err).toBeInstanceOf(IndexMismatchError);
        expect(err.message).toMatch(/useIndex: false/);
      }
      // Also when only part of the index is read
      const [z, x, y] = TILES[3];
      await expect(tile(connector, z, x, y, { name: 'l', path: fixture('gogama-indexdata-points.fgb') }, { cache: false }))
        .rejects.toBeInstanceOf(IndexMismatchError);
    });

    it('read correctly when scanned', async () => {
      for (const [z, x, y] of TILES) {
        const gdal = await pointsByLabel(fixture('points.fgb'), z, x, y);
        expect(await pointsByLabel(fixture('gogama-indexdata-points.fgb'), z, x, y, false)).toEqual(gdal);
      }
      const polygons = decodeLayer(await tile(connector, 0, 0, 0, {
        name: 'l', path: fixture('gogama-indexdata-polygons.fgb'), useIndex: false,
      }), 'l');
      expect(polygons?.length).toBe(30);
    });
  });
});

/**
 * A tile's features as comparable records, sorted by content: writers store
 * features in different orders (GDAL sorts them along its index).
 */
async function tileFeatures(path: string, z: number, x: number, y: number, source: Partial<Source> = {}) {
  const layer = decodeLayer(await tile(connector, z, x, y, { name: 'l', path, ...source }), 'l');
  return features(layer)
    .map(f => ({
      id: f.id,
      type: f.type,
      properties: f.properties,
      geometry: f.loadGeometry().map(part => part.map(p => [p.x, p.y])),
    }))
    .map(f => [JSON.stringify(f), f] as const)
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([, f]) => f);
}

/** z0 plus the tiles containing each lon/lat at several zooms, without duplicates. */
function tilesAround(points: Array<[number, number]>): Array<[number, number, number]> {
  const out = new Map<string, [number, number, number]>([['0/0/0', [0, 0, 0]]]);
  for (const [lon, lat] of points) {
    for (const z of [2, 5, 8, 11, 14]) {
      const { x, y } = tileAt(lon, lat, z);
      out.set(`${z}/${x}/${y}`, [z, x, y]);
    }
  }
  return [...out.values()];
}

/**
 * Fixtures written by the flatgeobuf npm package and the GDAL fixtures with
 * the same features, with points on the data (ring vertices, line
 * vertices) whose tiles are compared.
 */
const JS_FIXTURES: Array<[js: string, gdal: string, points: Array<[number, number]>]> = [
  ['flatgeobuf-js-points.fgb', 'points.fgb', [[-96, 32], [-95.5, 31.5]]],
  ['flatgeobuf-js-points.fgb', 'no-index.fgb', [[-96, 32], [-95.5, 31.5]]],
  // GDAL 3.4.1 itself cannot read this file: it requires `ends` on the
  // single-part MultiLineString, which this writer leaves out
  ['flatgeobuf-js-lines.fgb', 'lines.fgb', [
    [-95, 45 + 0.2 * Math.sin(500 / 20)], [-97, 44 + 0.2 * Math.sin(300 / 20)], [-92, 43 + 0.2 * Math.sin(200 / 20)],
  ]],
  ['flatgeobuf-js-multipolygons.fgb', 'multipolygons.fgb', [[-88, 40], [-79, 40], [-75, 40], [-68, 40], [-69, 40]]],
  ['flatgeobuf-js-single.fgb', 'single.fgb', [[11, 10]]],
  ['flatgeobuf-js-mixed.fgb', 'mixed.fgb', [[-100, 40], [-100, 39], [-99, 41], [-94, 39], [-92, 38], [-94, 40]]],
  // Z and M are written per feature only (the header has no has_z/has_m)
  ...['xy', 'xyz', 'xym', 'xyzm'].map((dims): [string, string, Array<[number, number]>] => [
    `flatgeobuf-js-dims-${dims}.fgb`, `dims-${dims}.fgb`, [[-100, 40], [-100, 39.5], [-96, 39], [-95.5, 40.5]],
  ]),
];

/** Fixture header. */
function headerOf(file: string) {
  return parseHeader(new Uint8Array(readFileSync(fixture(file))));
}

/**
 * The flatgeobuf package (v4.6.1, `geojson.serialize`) differs from GDAL in
 * what it can write, not in the features:
 * - no spatial index and no envelope: every file is scanned;
 * - every number becomes a Double column, so there is no integer `id`
 *   column to take feature ids from; the comparisons use `idColumn: false`
 *   on both files, which leaves `id` as a property in both;
 * - the CRS is a bare code (org null, meaning EPSG), or absent.
 * Ring vertices computed with V8's sin/cos differ from GDAL's (C library) in
 * the last bit in a few places; no tile changes.
 */
describe('flatgeobuf (JS)', () => {
  it.each(JS_FIXTURES)('%s renders the same tiles as GDAL\'s %s', async (js, gdal, points) => {
    for (const [z, x, y] of tilesAround(points)) {
      const expected = await tileFeatures(fixture(gdal), z, x, y, { idColumn: false });
      expect(expected.length, `${gdal} ${z}/${x}/${y}`).toBeGreaterThan(0);
      expect(await tileFeatures(fixture(js), z, x, y, { idColumn: false }), `${js} ${z}/${x}/${y}`).toEqual(expected);
    }
  });

  it('writes tiles byte for byte like GDAL\'s for the same features in the same order', async () => {
    // no-index.fgb is points.fgb unindexed, with features in input order like the JS file
    const pairs: Array<[string, string, Array<[number, number]>]> = [
      ['flatgeobuf-js-points.fgb', 'no-index.fgb', [[-96, 32], [-95.5, 31.5]]],
      ['flatgeobuf-js-single.fgb', 'single.fgb', [[11, 10]]],
    ];
    for (const [js, gdal, points] of pairs) {
      for (const [z, x, y] of tilesAround(points)) {
        const expected = await tile(connector, z, x, y, { name: 'l', path: fixture(gdal), idColumn: false });
        expect(await tile(connector, z, x, y, { name: 'l', path: fixture(js), idColumn: false }), `${js} ${z}/${x}/${y}`)
          .toEqual(expected);
      }
    }
  });

  it('reads the header: no index or envelope, numbers as Double, CRS as a bare code', () => {
    const points = headerOf('flatgeobuf-js-points.fgb');
    expect(points).toMatchObject({
      geometryType: GeomType.Point, featuresCount: 200, indexNodeSize: 0, indexSize: 0, bbox: null, idColumnIndex: -1, name: 'L1',
    });
    expect(points.crs).toMatchObject({ org: null, code: 4326 });
    expect(points.columns.map(c => [c.name, c.type])).toEqual([
      ['id', ColumnType.Double], ['big', ColumnType.Double], ['ts', ColumnType.Double], ['neg', ColumnType.Double],
      ['small', ColumnType.Double], ['ratio', ColumnType.Double], ['label', ColumnType.String],
    ]);
    const types = Object.fromEntries(JS_FIXTURES.map(([js]) => [js, headerOf(js).geometryType]));
    expect(types).toEqual({
      'flatgeobuf-js-points.fgb': GeomType.Point,
      'flatgeobuf-js-lines.fgb': GeomType.Unknown,
      'flatgeobuf-js-multipolygons.fgb': GeomType.MultiPolygon,
      'flatgeobuf-js-single.fgb': GeomType.Polygon,
      'flatgeobuf-js-mixed.fgb': GeomType.Unknown,
      'flatgeobuf-js-dims-xy.fgb': GeomType.Unknown,
      'flatgeobuf-js-dims-xyz.fgb': GeomType.Unknown,
      'flatgeobuf-js-dims-xym.fgb': GeomType.Unknown,
      'flatgeobuf-js-dims-xyzm.fgb': GeomType.Unknown,
    });
    expect(headerOf('flatgeobuf-js-lines.fgb').crs).toBeNull();
  });

  it('writes no feature ids by default, and rejects the Double id column as idColumn', async () => {
    const path = fixture('flatgeobuf-js-points.fgb');
    const all = features(decodeLayer(await tile(connector, 0, 0, 0, { name: 'l', path }), 'l'));
    expect(all).toHaveLength(200);
    expect(all.filter(f => f.id !== undefined)).toEqual([]);
    expect(all.map(f => f.properties.id).sort((a, b) => Number(a) - Number(b))).toEqual([...Array(200).keys()]);
    await expect(tile(connector, 0, 0, 0, { name: 'l', path, idColumn: 'id' })).rejects.toThrow(/not an integer column/);
  });
});
